select

from ingestion_task
where id = #{taskId}
  and kb_id = #{kbId}

select

from ingestion_task
where created_by = #{createdBy}
  and client_request_id = #{clientRequestId}
limit 1

select

from ingestion_task
where kb_id = #{kbId}

  and status = #{status}

order by created_at desc, id desc
limit #{limit}

mapper.update:
update ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
set iti.parse_attempt = #{parseAttempt},
    iti.docling_request_id = #{doclingRequestId},
    iti.source_revision = #{sourceRevision},
    iti.updated_at = #{updatedAt}
where it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}
  and iti.parse_attempt = #{parseAttempt}
  and (iti.docling_request_id is null or iti.docling_request_id = #{doclingRequestId})
  and (iti.source_revision is null or iti.source_revision = #{sourceRevision})

update ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
set iti.docling_job_id = #{doclingJobId},
    iti.updated_at = #{updatedAt}
where it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}
  and iti.docling_request_id = #{doclingRequestId}

update ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
set iti.stage = #{stage},
    iti.status = 'SUCCESS',
    iti.progress = #{progress},
    iti.error_code = null,
    iti.error_message = null,
    iti.updated_at = #{updatedAt},
    iti.finished_at = #{updatedAt}
where it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}

update ingestion_task_item iti
inner join ingestion_task it on it.id = iti.task_id
set iti.stage = #{stage},
    iti.status = 'FAILED',
    iti.progress = #{progress},
    iti.error_code = #{errorCode},
    iti.error_message = #{errorMessage},
    iti.updated_at = #{updatedAt},
    iti.finished_at = #{updatedAt}
where it.kb_id = #{kbId}
  and it.id = #{taskId}
  and iti.id = #{itemId}
